    const sailor = (store.sailors || []).find(
      (s) => String(s.id) === sailorId || (s._fbKey && String(s._fbKey) === sailorId),
    );
    if (!sailor) return;

    // Check leave
    const [yyyy, mm, dd] = dateVal.split("-");
