// ── Update Live Formatted Naval Minute Sheet Preview (Pic 1, 2, 3 Authentic Layout) ──
function updateMinuteSheetPreview() {
  const previewArea = document.getElementById("minuteSheetPrintArea");
  if (!previewArea) return;

  const lang = store.msLanguage || "si";
  const langTitle = lang === "si" ? "මාණ්ඩලික සටහන්පත" : "MINUTESHEET";
  const langM01 = lang === "si" ? "මා.ස 01" : "M-01";
  const langM02 = lang === "si" ? "මා.ස 02" : "M-02";

  const marginWidth = store.msMarginWidth || 28;
  const rightMargin = store.msRightMargin || 14;
  const fontFamily = store.msFontFamily || "serif";
  const fontSize = store.msFontSize || 12;
  const contentWidth = 100 - marginWidth;

  // Sync margin and font displays
  const marginDisplay1 = document.getElementById("msMarginWidthDisplay");
  const marginDisplay2 = document.getElementById("printMarginDisplay");
  const rightMarginDisplay = document.getElementById("msRightMarginDisplay");
  const fontSelect = document.getElementById("msInputFontFamily");
  const fontSizeSlider = document.getElementById("msInputFontSize");
  const fontSizeDisplay = document.getElementById("msFontSizeDisplay");

  if (marginDisplay1) marginDisplay1.textContent = `${marginWidth}%`;
  if (marginDisplay2) marginDisplay2.textContent = `${marginWidth}%`;
  if (rightMarginDisplay) rightMarginDisplay.textContent = `${rightMargin}px`;
  if (fontSelect && fontSelect.value !== fontFamily) fontSelect.value = fontFamily;
  if (fontSizeSlider && fontSizeSlider.value != fontSize) fontSizeSlider.value = fontSize;
  if (fontSizeDisplay) fontSizeDisplay.textContent = `${fontSize}px`;

  // Ensure Sinhala date if Sinhala mode
  let dateVal = document.getElementById("msInputDate")?.value || "";
  if (!dateVal || (lang === "si" && !dateVal.includes("මස") && (dateVal.includes("Aug") || dateVal.includes("-")))) {
    dateVal = getSinhalaDateString();
    const dInp = document.getElementById("msInputDate");
    if (dInp) dInp.value = dateVal;
  } else if (!dateVal) {
    dateVal = lang === "si" ? getSinhalaDateString() : getEnglishNavalDateString();
  }

  const subjectVal = document.getElementById("msInputSubject")?.value || (lang === "si" ? "නිවාඩු දීර්ඝ කිරීම සදහා" : "SUBJECT OF MINUTE");
  const originatorVal = document.getElementById("msInputOriginator")?.value || "";
  const recVal = document.getElementById("msInputRecommendation")?.value || "";
  const signTitleVal = document.getElementById("msInputSignatoryTitle")?.value || "";

  // Paragraphs (Pic 1 Layout: Wrapped lines align flush left with paragraph number 1.)
  const paraInputs = document.querySelectorAll(".ms-para-input");
  const paragraphs = [];
  paraInputs.forEach((inp) => {
    if (inp.value.trim()) paragraphs.push(inp.value.trim());
  });

  const parasHtml = paragraphs.map((p, i) => {
    const formattedBody = formatMinuteRichText(p);
    return `
      <div class="text-justify text-xs leading-relaxed text-black font-serif mb-2.5" style="font-size: ${fontSize}px !important; line-height: 1.6;">
        <span class="font-bold font-sans">${i + 1}.</span>&emsp;&emsp;${formattedBody}
      </div>
    `;
  }).join("");

  // All Addressee lines from multiple dropdown/custom boxes shown one after another
  const addRows = document.querySelectorAll(".ms-addressee-row");
  const addresseesList = [];
  if (addRows.length > 0) {
    addRows.forEach((row) => {
      const select = row.querySelector(".ms-addressee-select");
      const customInp = row.querySelector(".ms-addressee-custom-input");
      if (select && select.value === "__custom__" && customInp && customInp.value.trim()) {
        addresseesList.push(customInp.value.trim());
      } else if (select && select.value && select.value !== "__custom__") {
        addresseesList.push(select.value.trim());
      } else if (customInp && customInp.value.trim()) {
        addresseesList.push(customInp.value.trim());
      }
    });
  } else {
    const addInputs = document.querySelectorAll(".ms-addressee-input");
    addInputs.forEach((inp) => {
      if (inp.value.trim()) addresseesList.push(inp.value.trim());
    });
  }
  if (addresseesList.length === 0) {
    const legacy = document.getElementById("msInputAddressees")?.value;
    if (legacy && legacy.trim()) {
      addresseesList.push(...legacy.split("\n\n").map((a) => a.trim()).filter(Boolean));
    }
  }

  // Flatten and parse all addressees (splitting by multiple newlines if entered in a single block)
  const parsedAddressees = [];
  addresseesList.forEach((item) => {
    if (!item) return;
    const parts = item.split(/\n\s*\n+/).map((p) => p.trim()).filter(Boolean);
    if (parts.length > 0) {
      parsedAddressees.push(...parts);
    } else if (item.trim()) {
      parsedAddressees.push(item.trim());
    }
  });

  // Process Addressees List (Center Aligned with 3-Enter generous spacing between each officer)
  let firstAddresseeHtml = `<div class="font-bold italic text-slate-400 text-center">යොමුව (Addressee)</div>`;
  let subsequentAddresseesHtml = "";

  if (parsedAddressees.length > 0) {
    firstAddresseeHtml = `<div class="font-bold leading-snug text-black break-words text-center" style="overflow-wrap: anywhere; word-break: break-word; font-size: ${fontSize}px !important; line-height: 1.35;">${parsedAddressees[0].replace(/\n/g, "<br>")}</div>`;
    if (parsedAddressees.length > 1) {
      subsequentAddresseesHtml = parsedAddressees.slice(1).map((a) => `
        <div class="font-bold leading-snug text-black break-words text-center" style="overflow-wrap: anywhere; word-break: break-word; font-size: ${fontSize}px !important; line-height: 1.35; margin-top: 3.8em !important; padding-top: 0.6em;">
          ${a.replace(/\n/g, "<br>")}
        </div>
      `).join("");
    }
  }

  // M-02 (Subsequent Endorsement) - Placed below M-01 with NO horizontal divider border
  const isM02Enabled = document.getElementById("msEnableM02")?.checked;
  let m02Html = "";
  if (isM02Enabled) {
    const m02Originator = document.getElementById("msM02Originator")?.value || (lang === "si" ? "විධායක නිලධාරි මඟින්" : "Executive Officer");
    const m02Text = document.getElementById("msM02Text")?.value || (lang === "si" ? "නිර්දේශ කර ඉදිරිපත් කරමි." : "Recommended and forwarded please.");
    let m02Date = document.getElementById("msM02Date")?.value || dateVal;
    if (lang === "si" && !m02Date.includes("මස") && (m02Date.includes("Aug") || m02Date.includes("-"))) {
      m02Date = getSinhalaDateString();
    }
    const m02SignTitle = document.getElementById("msM02SignTitle")?.value || (lang === "si" ? "නියෝජ්‍ය ප්‍රධාන ඉංජිනේරු" : "Deputy Chief Engineer");

    m02Html = `
      <!-- Minute 02 Block -->
      <div class="pt-8 space-y-3">
        <!-- M-02 Header -->
        <div class="text-center font-bold text-xs pb-1 text-black">
          <u>${langM02}</u>
        </div>

        <!-- M-02 Originator Designation (Pic 2) -->
        ${m02Originator ? `
        <div class="font-bold text-xs text-black leading-snug inline-block">
          <u>${m02Originator}</u>
        </div>` : ""}

        <!-- M-02 Action / Endorsement Text -->
        <div class="text-xs leading-relaxed text-black font-serif text-justify">
          <p>&emsp;&emsp;${m02Text}</p>
        </div>

        <!-- M-02 Date & Signatory Block -->
        <div class="pt-6 flex items-end justify-between">
          <div class="font-bold text-xs text-black">
            ${m02Date}
          </div>
          <div class="text-center min-w-[160px] space-y-0.5">
            <div class="h-10"></div> <!-- Signature blank space -->
            ${m02SignTitle ? `<p class="font-bold text-[11px] text-slate-900">${m02SignTitle}</p>` : ""}
          </div>
        </div>
      </div>
    `;
  }

  // Final HTML rendered on Paper Surface with Exact Alignment (Pic 1 Authentic Naval Format)
  const renderedContent = `
    <div class="w-full bg-white text-black naval-minute-paper flex flex-col" style="font-family: ${fontFamily} !important; font-size: ${fontSize}px !important; min-height: 940px;">
      <!-- Title Header (Centered & Underlined) -->
      <div class="text-center pb-2 flex-shrink-0">
        <h2 class="inline-block font-bold uppercase underline tracking-wider text-black" style="font-size: ${fontSize + 2}px !important;">
          ${langTitle}
        </h2>
      </div>

      <!-- Table without outer borders - Top black horizontal line intersects with vertical divider line (Pic 1) -->
      <table class="w-full border-collapse leading-relaxed flex-1" style="border:none !important; border-top: 1.5px solid #000 !important; width:100%; min-height: 860px; font-family: ${fontFamily} !important; font-size: ${fontSize}px !important;">
        <!-- Top Subject Row (With Top-Left Reference: "යොමුව" / "Ref") -->
        <tr style="border:none !important; height: auto;">
          <td style="width: ${marginWidth}%; border-right: 1.5px solid #000 !important; border-bottom: 1.5px solid #000 !important; border-top:none !important; border-left:none !important; padding: 6px 10px; font-size: ${fontSize}px !important;" class="text-center font-bold text-black align-middle">
            ${lang === "si" ? "යොමුව" : "Ref"}
          </td>
          <td style="width: ${contentWidth}%; border-bottom: 1.5px solid #000 !important; border-top:none !important; border-right:none !important; padding: 6px ${rightMargin}px 6px 12px; font-size: ${fontSize}px !important;" class="text-center font-bold align-middle tracking-wide text-black uppercase">
            <u>${subjectVal}</u>
          </td>
        </tr>

        <!-- M-01 Header Level Row -->
        <tr style="border:none !important; height: auto;">
          <td style="width: ${marginWidth}%; border-right: 1.5px solid #000 !important; border-bottom:none !important; border-top:none !important; padding: 6px 10px 0 10px;" class="align-top">
            <!-- Space matching M-01 header -->
            <div class="invisible select-none font-bold pb-1" aria-hidden="true" style="font-size: ${fontSize}px !important;"><u>${langM01}</u></div>
          </td>
          <td style="width: ${contentWidth}%; border:none !important; padding: 6px ${rightMargin}px 0 14px;" class="text-center align-top">
            <div class="font-bold pb-1 inline-block text-black" style="font-size: ${fontSize}px !important;">
              <u>${langM01}</u>
            </div>
          </td>
        </tr>

        <!-- Originator & 1st Addressee Row (Guaranteed Exact Same Baseline Alignment - Pic 1) -->
        <tr style="border:none !important; height: auto;">
          <!-- Left: 1st Addressee -->
          <td style="width: ${marginWidth}%; border-right: 1.5px solid #000 !important; border-bottom:none !important; border-top:none !important; padding: 4px 10px 0 10px; font-size: ${fontSize}px !important;" class="align-top font-bold leading-snug text-black">
            ${firstAddresseeHtml}
          </td>
          <!-- Right: Originator -->
          <td style="width: ${contentWidth}%; border:none !important; padding: 4px ${rightMargin}px 0 14px;" class="align-top">
            ${originatorVal ? `<div class="font-bold text-black leading-snug inline-block" style="font-size: ${fontSize}px !important;"><u>${originatorVal}</u></div>` : ""}
          </td>
        </tr>

        <!-- Main Body Row: Paragraphs & Subsequent Addressees (Vertical divider line continues down to bottom of page) -->
        <tr style="border:none !important; height: 100%;">
          <!-- Left: Subsequent Addressees (Vertical line continues all the way down) -->
          <td style="width: ${marginWidth}%; border-right: 1.5px solid #000 !important; border-bottom:none !important; border-top:none !important; padding: 0 10px 14px 10px; height: 100%;" class="align-top">
            ${subsequentAddresseesHtml}
          </td>

          <!-- Right Column: Paragraphs, Recommendation, Date/Signatory, M-02 -->
          <td style="width: ${contentWidth}%; border:none !important; padding: 6px ${rightMargin}px 14px 14px; height: 100%;" class="align-top space-y-3">
            <!-- Paragraphs (Pic 1 Style) -->
            <div class="space-y-2 text-justify leading-relaxed text-black" style="font-size: ${fontSize}px !important;">
              ${parasHtml || `<p class="italic text-slate-400">No paragraph content entered yet.</p>`}
            </div>

            <!-- Recommendation / Final Clause -->
            ${recVal ? `
            <div class="pt-1 font-semibold text-black leading-relaxed" style="font-size: ${fontSize}px !important;">
              <p>${formatMinuteRichText(recVal)}</p>
            </div>` : ""}

            <!-- Date (Left) & Signature Block (Right) -->
            <div class="pt-6 flex items-end justify-between">
              <!-- Date -->
              <div class="font-bold text-black" style="font-size: ${fontSize}px !important;">
                ${dateVal}
              </div>

              <!-- Signature Space & Appointment -->
              <div class="text-center min-w-[160px] space-y-0.5">
                <div class="h-10"></div> <!-- Signature space -->
                ${signTitleVal ? `<p class="font-bold text-slate-900" style="font-size: ${Math.max(10, fontSize - 1)}px !important;">${signTitleVal}</p>` : ""}
              </div>
            </div>

            <!-- M-02 Block -->
            ${m02Html}
          </td>
        </tr>
      </table>
    </div>
  `;

  previewArea.innerHTML = renderedContent;

  // Mirror to Modal Preview if open
  const modalPreviewArea = document.getElementById("minuteSheetModalPrintArea");
  if (modalPreviewArea) {
    modalPreviewArea.innerHTML = renderedContent;
  }
}

// Universal Clean Printing Helper for Documents & Slips
function printElement(elementId, docTitle = "Sri Lanka Navy - Document Print") {
  const el = typeof elementId === "string" ? document.getElementById(elementId) : elementId;
  if (!el) {
    window.print();
    return;
  }

  const printWindow = window.open("", "_blank", "width=900,height=750");
  if (!printWindow) {
    window.print();
    return;
  }

  const isBw = store.msColorMode === "bw";
  const paperSize = store.msPaperSize === "letter" ? "letter" : "A4";

  printWindow.document.write(`
    <!DOCTYPE html>
    <html>
      <head>
        <title>${docTitle}</title>
        <script src="https://cdn.tailwindcss.com"></script>
        <style>
          @page {
            size: ${paperSize} portrait;
            margin: 15mm 15mm 15mm 15mm;
          }
          body {
            font-family: "Times New Roman", Times, Georgia, "Iskoola Pota", "Noto Sans Sinhala", serif, Arial, sans-serif;
            background: #ffffff;
            color: #000000;
            margin: 0;
            padding: 0;
            ${isBw ? "filter: grayscale(100%);" : ""}
          }
          table {
            border-collapse: collapse !important;
            border: none !important;
          }
          @media print {
            .no-print { display: none !important; }
            body { padding: 0; margin: 0; }
          }
        </style>
      </head>
      <body class="p-6">
        <div class="max-w-4xl mx-auto">
          ${el.innerHTML}
        </div>
        <script>
          window.onload = function() {
            setTimeout(function() {
              window.print();
              window.close();
            }, 300);
          };
        </script>
      </body>
    </html>
  `);
  printWindow.document.close();
}

// Print Minute Sheet Shortcut
function printMinuteSheetDocument() {
  openMinutePrintSetupModal();
}

// Save Minute Record
function saveMinuteSheetRecord() {
  const refNo = document.getElementById("msInputRefNo")?.value || "MIN/2026/08/XXX";
  showToast(`Minute Sheet ${refNo} saved to records!`, "success");
}

// Save Current Minute Builder as a New Template
function saveMinuteAsNewTemplate() {
  const title = prompt("Enter a title for this new Minute Template (නව ආකෘතියේ නම ඇතුළත් කරන්න):");
  if (!title) return;

  const lang = store.msLanguage || "si";
  const refNo = document.getElementById("msInputRefNo")?.value || "MIN/2026/08/XXX";
  const subjectVal = document.getElementById("msInputSubject")?.value || "SUBJECT";
  
  const addRows = document.querySelectorAll(".ms-addressee-row");
  const addresseesList = [];
  if (addRows.length > 0) {
    addRows.forEach((row) => {
      const select = row.querySelector(".ms-addressee-select");
      const customInp = row.querySelector(".ms-addressee-custom-input");
      if (select && select.value === "__custom__" && customInp && customInp.value.trim()) {
        addresseesList.push(customInp.value.trim());
      } else if (select && select.value && select.value !== "__custom__") {
        addresseesList.push(select.value.trim());
      } else if (customInp && customInp.value.trim()) {
        addresseesList.push(customInp.value.trim());
      }
    });
  } else {
    const addInputs = document.querySelectorAll(".ms-addressee-input");
    addInputs.forEach((inp) => {
      if (inp.value.trim()) addresseesList.push(inp.value.trim());
    });
  }
  const addresseesVal = addresseesList.join("\n\n");

  const originatorVal = document.getElementById("msInputOriginator")?.value || "";
  const recVal = document.getElementById("msInputRecommendation")?.value || "";
  const signTitleVal = document.getElementById("msInputSignatoryTitle")?.value || "";

  const paraInputs = document.querySelectorAll(".ms-para-input");
  const paragraphs = [];
  paraInputs.forEach((inp) => {
    if (inp.value.trim()) paragraphs.push(inp.value.trim());
  });

  const isM02Enabled = document.getElementById("msEnableM02")?.checked || false;
  const m02Addressee = document.getElementById("msM02Addressee")?.value || "";
  const m02Originator = document.getElementById("msM02Originator")?.value || "";
  const m02Text = document.getElementById("msM02Text")?.value || "";
  const m02SignTitle = document.getElementById("msM02SignTitle")?.value || "";

  const newTpl = {
    id: `tpl_${Date.now()}`,
    lang: lang,
    title: title,
    category: "Custom Templates",
    ref_no: refNo,
    subject: subjectVal,
    addressees: addresseesVal,
    originator: originatorVal,
    paragraphs: paragraphs,
    recommendation: recVal,
    sign_title: signTitleVal,
    m02_enabled: isM02Enabled,
    m02_addressee: m02Addressee,
    m02_originator: m02Originator,
    m02_text: m02Text,
    m02_sign_title: m02SignTitle
  };

  store.minuteTemplates.push(newTpl);
  saveMinuteTemplatesToStorage();
  updateDocumentsMetricStats();
  populateMinuteSheetDropdowns();
  showToast(`Template "${title}" saved to Inventory!`, "success");
}

// Render Templates Inventory Grid
function renderMinuteTemplatesInventory() {
  const grid = document.getElementById("minuteTemplatesGrid");
  if (!grid) return;

  const templates = store.minuteTemplates || [];
  if (templates.length === 0) {
    grid.innerHTML = `
      <div class="col-span-full p-8 border border-dashed border-slate-300 rounded-2xl text-center text-slate-400">
        No templates found. Click <strong>+ Add New Template</strong> to create one.
      </div>
    `;
    return;
  }

  grid.innerHTML = templates.map((t) => `
    <div class="bg-white p-5 rounded-2xl border border-slate-200 shadow-xs flex flex-col justify-between space-y-3 hover:shadow-md transition-all">
      <div class="space-y-2">
        <div class="flex items-center justify-between">
          <span class="text-[10px] font-black uppercase tracking-wider px-2 py-0.5 rounded ${t.lang === "si" ? "bg-emerald-50 text-emerald-700 border border-emerald-200" : "bg-purple-50 text-purple-700 border border-purple-200"}">
            ${t.lang === "si" ? "🇱🇰 සිංහල" : "🇬🇧 English"} • ${t.category || "Civil Works"}
          </span>
          <span class="text-[10px] text-slate-400 font-mono">${(t.paragraphs || []).length} Paragraphs</span>
        </div>
        <h4 class="text-sm font-black text-slate-800">${t.title}</h4>
        <p class="text-xs text-slate-600 font-medium line-clamp-2">
          <strong>Subject:</strong> ${t.subject || "—"}
        </p>
        <p class="text-[11px] text-slate-500 line-clamp-2 italic">
          "${(t.paragraphs && t.paragraphs[0]) ? t.paragraphs[0] : t.recommendation || ""}"
        </p>
      </div>

      <div class="pt-3 border-t border-slate-100 flex items-center justify-between gap-2">
        <button onclick="loadMinuteTemplateIntoCreator('${t.id}')" class="flex-1 py-2 bg-teal-600 hover:bg-teal-700 text-white rounded-xl text-xs font-bold shadow-xs transition-all cursor-pointer flex items-center justify-center gap-1.5">
          <span>✍️</span> Use Template
        </button>
        <button onclick="openNewMinuteTemplateModal('${t.id}')" class="px-2.5 py-2 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-xl text-xs font-bold transition-all cursor-pointer" title="Edit Template">
          ✏️
        </button>
        <button type="button" onclick="deleteMinuteTemplate('${t.id}', event)" class="px-2.5 py-2 bg-rose-50 hover:bg-rose-100 text-rose-700 rounded-xl text-xs font-bold transition-all cursor-pointer" title="Delete Template">
          🗑️
        </button>
      </div>
    </div>
  `).join("");
}

// Load Selected Template Into Builder
function loadMinuteTemplateIntoCreator(templateId) {
  const tpl = (store.minuteTemplates || []).find((t) => t.id === templateId) ||
              DEFAULT_NAVAL_MINUTE_TEMPLATES.find((t) => t.id === templateId);
  if (!tpl) return;

  switchDocumentsSubTab("minutesheet");

  // Set Language
  if (tpl.lang) {
    setMinuteSheetLanguage(tpl.lang);
  }

  const refInput = document.getElementById("msInputRefNo");
  if (refInput && tpl.ref_no) refInput.value = tpl.ref_no;

  const dateInput = document.getElementById("msInputDate");
  if (dateInput) {
    dateInput.value = tpl.lang === "si" ? getSinhalaDateString() : getEnglishNavalDateString();
  }

  const subInput = document.getElementById("msInputSubject");
  if (subInput) subInput.value = tpl.subject || "";

  const addContainer = document.getElementById("msAddresseesContainer");
  if (addContainer) {
    addContainer.innerHTML = "";
    const rawAdd = tpl.addressees || (tpl.to ? `${tpl.to}\n\n${tpl.through || ""}`.trim() : "");
    if (rawAdd) {
      rawAdd.split("\n\n").join("\n").split("\n").map((a) => a.trim()).filter(Boolean).forEach((a) => {
        addMinuteAddresseeInput(a);
      });
    }
  }

  const oriInput = document.getElementById("msInputOriginator");
  if (oriInput) oriInput.value = tpl.originator || tpl.from || "";

  const recInput = document.getElementById("msInputRecommendation");
  if (recInput) recInput.value = tpl.recommendation || "";

  const sigInput = document.getElementById("msInputSignatoryTitle");
  if (sigInput) sigInput.value = tpl.sign_title || tpl.from || "";

  // Paragraphs
  const container = document.getElementById("msParagraphsContainer");
  if (container) {
    container.innerHTML = "";
    (tpl.paragraphs || []).forEach((p) => {
      addMinuteParagraphInput(p);
    });
  }

  // Minute 02
  const m02Check = document.getElementById("msEnableM02");
if (m02Check) {
    m02Check.checked = !!tpl.m02_enabled;
    toggleMinute02Section();
    if (tpl.m02_enabled) {
      const aInput = document.getElementById("msM02Addressee");
      if (aInput) aInput.value = tpl.m02_addressee || "";
      const oInput = document.getElementById("msM02Originator");
      if (oInput) oInput.value = tpl.m02_originator || "";
      const tInput = document.getElementById("msM02Text");
      if (tInput) tInput.value = tpl.m02_text || "";
      const sInput = document.getElementById("msM02SignTitle");
      if (sInput) sInput.value = tpl.m02_sign_title || "";
    }
  }

  updateMinuteSheetPreview();
  showToast(`Loaded "${tpl.title}" template into Builder!`, "success");
}

// Open Template Editor Modal
function openNewMinuteTemplateModal(templateId = null) {
  const idInput = document.getElementById("emtTemplateId");
  const titleInput = document.getElementById("emtTitle");
  const catInput = document.getElementById("emtCategory");
  const toInput = document.getElementById("emtTo");
  const subInput = document.getElementById("emtSubject");
  const bodyInput = document.getElementById("emtBody");
  const recInput = document.getElementById("emtRecommendation");
  const modalTitle = document.getElementById("emtModalTitle");

  if (templateId) {
    const tpl = (store.minuteTemplates || []).find((t) => t.id === templateId);
    if (tpl) {
      if (idInput) idInput.value = tpl.id;
      if (titleInput) titleInput.value = tpl.title;
      if (catInput) catInput.value = tpl.category || "Civil Works";
      if (toInput) toInput.value = tpl.addressees || tpl.to || "";
      if (subInput) subInput.value = tpl.subject || "";
      if (bodyInput) bodyInput.value = (tpl.paragraphs || []).join("\n\n");
      if (recInput) recInput.value = tpl.recommendation || "";
      if (modalTitle) modalTitle.textContent = "Edit Minute Template";
    }
  } else {
    if (idInput) idInput.value = "";
    if (titleInput) titleInput.value = "";
    if (catInput) catInput.value = "Civil Works";
    if (toInput) toInput.value = "විධායක නිලධාරි (තඨාකාංගනය)";
    if (subInput) subInput.value = "";
    if (bodyInput) bodyInput.value = "";
    if (recInput) recInput.value = "කරුණු එසේ හෙයින් කාරුණික අනුමැතිය අයදිමි.";
    if (modalTitle) modalTitle.textContent = "Add New Template to Inventory";
  }

  const modal = document.getElementById("editMinuteTemplateModal");
  if (modal) modal.classList.remove("hidden");
}

// Save Custom Template
function saveCustomMinuteTemplate() {
  const id = document.getElementById("emtTemplateId")?.value;
  const title = document.getElementById("emtTitle")?.value;
  const category = document.getElementById("emtCategory")?.value || "Civil Works";
  const to = document.getElementById("emtTo")?.value || "Chief Engineer";
  const subject = document.getElementById("emtSubject")?.value || "";
  const body = document.getElementById("emtBody")?.value || "";
  const rec = document.getElementById("emtRecommendation")?.value || "";

  const paragraphs = body.split("\n\n").map((p) => p.trim()).filter(Boolean);

  if (id) {
    const tpl = (store.minuteTemplates || []).find((t) => t.id === id);
    if (tpl) {
      tpl.title = title;
      tpl.category = category;
      tpl.addressees = to;
      tpl.subject = subject;
      tpl.paragraphs = paragraphs;
      tpl.recommendation = rec;
    }
  } else {
    const newTpl = {
      id: `tpl_${Date.now()}`,
      lang: store.msLanguage || "si",
      title: title,
      category: category,
      ref_no: "MIN/2026/08/XXX",
      addressees: to,
      originator: "කාර්ය භාර නිලධාරි මඟින්",
      subject: subject,
      paragraphs: paragraphs,
      recommendation: rec,
      sign_title: "කාර්ය භාර නිලධාරි"
    };
    store.minuteTemplates.push(newTpl);
  }

  saveMinuteTemplatesToStorage();
  closeModal("editMinuteTemplateModal");
  updateDocumentsMetricStats();
  renderMinuteTemplatesInventory();
  showToast(`Template "${title}" saved to Inventory!`, "success");
}

// Delete Template
function deleteMinuteTemplate(templateId, event) {
  if (event) {
    event.preventDefault();
    event.stopPropagation();
  }
  if (!confirm("Are you sure you want to delete this template from the Inventory?")) return;
  store.minuteTemplates = (store.minuteTemplates || []).filter((t) => t.id !== templateId);
  saveMinuteTemplatesToStorage();
  updateDocumentsMetricStats();
  renderMinuteTemplatesInventory();
  showToast("Template removed from Inventory", "info");
}


// ============================================================================
// ==================== TEMPORARY ISSUE BOOK (TIB) MODULE =====================
// ============================================================================

store.inventorySubTab = store.inventorySubTab || "stock";

// Sub-Tab Switcher in Inventory
function switchInventorySubTab(subTab) {
  store.inventorySubTab = subTab;
  const tabStock = document.getElementById("invSubTab-stock");
  const tabTIB = document.getElementById("invSubTab-tempissues");
  const tabPrecast = document.getElementById("invSubTab-precast");
  const tabNav254 = document.getElementById("invSubTab-nav254");

  const panelStock = document.getElementById("invPanel-stock");
  const panelTIB = document.getElementById("invPanel-tempissues");
  const panelPrecast = document.getElementById("invPanel-precast");
  const panelNav254 = document.getElementById("invPanel-nav254");

  const mainStockActions = document.getElementById("invMainStockActions");

  const inactiveBtn = "px-4 py-2 rounded-xl text-xs font-semibold bg-slate-100 hover:bg-slate-200 text-slate-700 transition-all flex items-center gap-1.5 cursor-pointer";
  const activeStockBtn = "px-4 py-2 rounded-xl text-xs font-bold bg-teal-600 text-white shadow-xs transition-all flex items-center gap-1.5 cursor-pointer";
  const activeTibBtn = "px-4 py-2 rounded-xl text-xs font-bold bg-indigo-600 text-white shadow-xs transition-all flex items-center gap-1.5 cursor-pointer";
  const activePrecastBtn = "px-4 py-2 rounded-xl text-xs font-bold bg-amber-600 text-white shadow-xs transition-all flex items-center gap-1.5 cursor-pointer";
  const activeNav254Btn = "px-4 py-2 rounded-xl text-xs font-bold bg-orange-600 text-white shadow-xs transition-all flex items-center gap-1.5 cursor-pointer";

  if (panelStock) panelStock.classList.toggle("hidden", subTab !== "stock");
  if (panelTIB) panelTIB.classList.toggle("hidden", subTab !== "tempissues");
  if (panelPrecast) panelPrecast.classList.toggle("hidden", subTab !== "precast");
  if (panelNav254) panelNav254.classList.toggle("hidden", subTab !== "nav254");

  if (mainStockActions) mainStockActions.classList.toggle("hidden", subTab !== "stock");

  if (tabStock) tabStock.className = subTab === "stock" ? activeStockBtn : inactiveBtn;
  if (tabTIB) tabTIB.className = subTab === "tempissues" ? activeTibBtn : inactiveBtn;
  if (tabPrecast) tabPrecast.className = subTab === "precast" ? activePrecastBtn : inactiveBtn;
  if (tabNav254) tabNav254.className = subTab === "nav254" ? activeNav254Btn : inactiveBtn;

  if (subTab === "tempissues") {
    renderTempIssuesDashboard();
    renderTempIssuesTable();
  } else if (subTab === "precast") {
    renderPrecastInventoryTable();
  } else if (subTab === "nav254") {
    renderNav254RegisterTable();
  }

  updateTibPendingBadge();
  updateNav254RegisterBadge();
}

function updateNav254RegisterBadge() {
  const countBadge = document.getElementById("nav254CountBadge");
  if (!countBadge) return;
  const count = (store.nav254Vouchers || []).length;
  countBadge.textContent = count;
}

function renderNav254RegisterTable() {
  const tbody = document.getElementById("nav254RegisterTableBody");
  if (!tbody) return;

  const searchVal = (document.getElementById("nav254RegisterSearch")?.value || "").toLowerCase().trim();
  const zoneFilter = document.getElementById("nav254ZoneFilter")?.value || "ALL";
  const sourceFilter = document.getElementById("nav254SourceFilter")?.value || "ALL";

  // 1. Gather all NAV 254 vouchers from store.nav254Vouchers
  let allRecords = [...(store.nav254Vouchers || [])];

  // 2. Also incorporate any legacy off-charge records in store.inventory if not already in nav254Vouchers
  (store.inventory || []).forEach((inv) => {
    if (inv.off_charge_records && Array.isArray(inv.off_charge_records)) {
      inv.off_charge_records.forEach((rec, idx) => {
        const refNo = rec.ref || `OFF-${inv.id || inv._fbKey}-${idx}`;
        const alreadyExists = allRecords.some((v) => (v.voucher_no === refNo || v.ref_no === refNo));
        if (!alreadyExists) {
          const unitPrice = parseFloat(inv.cost_per_unit || inv.cost || 0);
          allRecords.push({
            id: `synth_${inv.id || inv._fbKey}_${idx}`,
            voucher_no: refNo,
            ref_no: refNo,
            date: rec.date || getLocalDateString(),
            issuing_unit: `${inv.zone_id || store.currentZone || "Main Store"} Store`,
            receiving_unit: rec.dest || "Project / Base",
            authority: rec.ref || "Official Off-Charge",
            issued_by: "Store Keeper",
            received_by: rec.dest || "Receiver",
            items: [
              {
                inventory_id: inv._fbKey || inv.id,
                description: inv.description,
                deno: inv.deno || "Nos",
                quantity_demanded: rec.qty || 1,
                quantity_issued: rec.qty || 1,
                unit_cost: unitPrice,
                total_value: unitPrice * (rec.qty || 1)
              }
            ],
            remarks: rec.remarks || "",
            source: "Store Off-Charge",
            created_at: rec.timestamp || Date.now()
          });
        }
      });
    }
  });

  // Calculate Metrics before filtering
  let totalVouchers = allRecords.length;
  let totalItemsCount = 0;
  let totalValuation = 0;

  allRecords.forEach((v) => {
    (v.items || []).forEach((it) => {
      const q = parseFloat(it.quantity_issued || it.quantity || it.qty || 0);
      const val = parseFloat(it.total_value) || (q * (parseFloat(it.unit_cost) || 0));
      totalItemsCount += q;
      totalValuation += val;
    });
  });

  const kpiVouchers = document.getElementById("reg254TotalVouchers");
  if (kpiVouchers) kpiVouchers.textContent = `${totalVouchers} Vouchers`;

  const kpiItems = document.getElementById("reg254TotalItems");
  if (kpiItems) kpiItems.textContent = `${totalItemsCount.toLocaleString()} Units`;

  const kpiValue = document.getElementById("reg254TotalValue");
  if (kpiValue) kpiValue.textContent = formatCurrency(totalValuation);

  updateNav254RegisterBadge();

  // Filter Records
  let filtered = allRecords.filter((v) => {
    // Zone filter
    if (zoneFilter !== "ALL") {
      const matchIssuing = isZoneMatch(v.issuing_unit, zoneFilter) || (v.issuing_unit || "").toLowerCase().includes(zoneFilter.toLowerCase());
      const matchReceiving = isZoneMatch(v.receiving_unit, zoneFilter) || (v.receiving_unit || "").toLowerCase().includes(zoneFilter.toLowerCase());
      if (!matchIssuing && !matchReceiving) return false;
    }

    // Source filter
    if (sourceFilter !== "ALL") {
      const src = v.source || (v.voucher_no && v.voucher_no.startsWith("NAV") ? "NAV 254 Voucher" : "Store Off-Charge");
      if (sourceFilter === "NAV 254 Voucher" && !src.includes("NAV")) return false;
      if (sourceFilter === "Store Off-Charge" && !src.includes("Off-Charge")) return false;
      if (sourceFilter === "TIB Issue" && !src.includes("TIB")) return false;
    }

    // Search filter
    if (searchVal) {
      const vNo = (v.voucher_no || v.ref_no || "").toLowerCase();
      const iss = (v.issuing_unit || "").toLowerCase();
      const rec = (v.receiving_unit || "").toLowerCase();
      const auth = (v.authority || "").toLowerCase();
      const by = (v.issued_by || "").toLowerCase();
      const rBy = (v.received_by || "").toLowerCase();
      const itemsMatch = (v.items || []).some((it) => (it.description || "").toLowerCase().includes(searchVal));
      if (!vNo.includes(searchVal) && !iss.includes(searchVal) && !rec.includes(searchVal) && !auth.includes(searchVal) && !by.includes(searchVal) && !rBy.includes(searchVal) && !itemsMatch) {
        return false;
      }
    }
    return true;
  });

  // Sort descending by date / created_at
  filtered.sort((a, b) => {
    const tA = a.created_at || (a.date ? new Date(a.date).getTime() : 0);
    const tB = b.created_at || (b.date ? new Date(b.date).getTime() : 0);
    return tB - tA;
  });

  if (filtered.length === 0) {
    tbody.innerHTML = `<tr><td colspan="8" class="text-center py-8 text-slate-400 font-medium italic">No NAV 254 or Off-Charge vouchers match the search criteria.</td></tr>`;
    return;
  }

  tbody.innerHTML = filtered.map((v) => {
    const vId = v.id || v._fbKey || v.voucher_no || "";
    const itemsList = v.items || [];
    const totalVal = itemsList.reduce((sum, it) => sum + (parseFloat(it.total_value) || ((parseFloat(it.quantity_issued || it.qty || 0)) * (parseFloat(it.unit_cost) || 0))), 0);
    const itemsSummaryHtml = itemsList.map((it) => `
      <div class="inline-flex items-center gap-1 px-2 py-0.5 rounded-md bg-slate-100 text-slate-800 text-[11px] font-medium border border-slate-200 mr-1 mb-1">
        <span>📦</span>
        <strong class="font-bold">${it.description}</strong>
        <span class="text-indigo-700 font-mono font-bold">(${it.quantity_issued || it.qty || 0} ${it.deno || "Nos"})</span>
      </div>
    `).join("");

    const srcBadge = v.source === "Store Off-Charge"
      ? `<span class="px-2 py-0.5 rounded-full text-[9px] font-extrabold bg-blue-100 text-blue-800 border border-blue-200">Store Off-Charge</span>`
      : `<span class="px-2 py-0.5 rounded-full text-[9px] font-extrabold bg-amber-100 text-amber-900 border border-amber-300">NAV 254 Official</span>`;

    return `
      <tr class="hover:bg-amber-50/30 transition-colors">
        <td class="px-3.5 py-3 align-top whitespace-nowrap">
          <div class="font-mono font-black text-xs text-amber-950">${v.voucher_no || v.ref_no || "NAV254"}</div>
          <div class="text-[10px] text-slate-400 font-mono mt-0.5">📅 ${v.date || "—"}</div>
          <div class="mt-1">${srcBadge}</div>
        </td>
        <td class="px-3.5 py-3 align-top">
          <div class="font-bold text-xs text-slate-800 flex items-center gap-1">
            <span>🏬</span> ${v.issuing_unit || "Main Store"}
          </div>
          <div class="text-[10px] text-slate-500 font-mono mt-0.5">Auth: ${v.authority || "Official"}</div>
        </td>
        <td class="px-3.5 py-3 align-top">
          <div class="font-bold text-xs text-indigo-900 flex items-center gap-1">
            <span>📍</span> ${v.receiving_unit || "—"}
          </div>
          ${v.received_by ? `<div class="text-[10px] text-slate-500 mt-0.5">Recv: ${v.received_by}</div>` : ""}
        </td>
        <td class="px-3.5 py-3 align-top max-w-xs">
          <div class="flex flex-wrap">${itemsSummaryHtml || '<span class="text-slate-400 italic">No item records</span>'}</div>
        </td>
        <td class="px-3.5 py-3 align-top text-right font-mono font-black text-emerald-700 whitespace-nowrap">
          ${formatCurrency(totalVal)}
        </td>
        <td class="px-3.5 py-3 align-top">
          <div class="font-semibold text-xs text-slate-800">${v.issued_by || "Store In-Charge"}</div>
          ${v.authorized_by ? `<div class="text-[10px] text-slate-500 mt-0.5">Approved: ${v.authorized_by}</div>` : ""}
        </td>
        <td class="px-3.5 py-3 align-top text-center whitespace-nowrap">
          <span class="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-bold bg-emerald-100 text-emerald-800 border border-emerald-300 shadow-2xs">
            <span>☁️</span> Recorded
          </span>
        </td>
        <td class="px-3.5 py-3 align-top text-center whitespace-nowrap">
          <div class="flex items-center justify-center gap-1">
            <button onclick="viewOrPrintNav254FromRegister('${vId}')" class="px-2.5 py-1.5 bg-amber-600 hover:bg-amber-700 text-white rounded-lg text-xs font-bold shadow-2xs transition-all flex items-center gap-1 cursor-pointer" title="View / Print Official NAV 254 Slip">
              <span>🖨️</span> Print Slip
            </button>
          </div>
        </td>
      </tr>
    `;
  }).join("");
}

function viewOrPrintNav254FromRegister(vId) {
  let v = (store.nav254Vouchers || []).find((x) => String(x.id) === String(vId) || String(x._fbKey) === String(vId) || String(x.voucher_no) === String(vId));
  
  if (!v) {
    // Try finding in inventory off-charge records
    (store.inventory || []).forEach((inv) => {
      (inv.off_charge_records || []).forEach((rec, idx) => {
        const refNo = rec.ref || `OFF-${inv.id || inv._fbKey}-${idx}`;
        if (refNo === vId || `synth_${inv.id || inv._fbKey}_${idx}` === vId) {
          const unitPrice = parseFloat(inv.cost_per_unit || inv.cost || 0);
          v = {
            voucher_no: refNo,
            ref_no: refNo,
            date: rec.date || getLocalDateString(),
            issuing_unit: `${inv.zone_id || store.currentZone || "Main Store"} Store`,
            receiving_unit: rec.dest || "Project / Base",
            authority: rec.ref || "Official Off-Charge",
            issued_by: "Store Keeper",
            received_by: rec.dest || "Receiver",
            items: [
              {
                description: inv.description,
                deno: inv.deno || "Nos",
                quantity_demanded: rec.qty || 1,
                quantity_issued: rec.qty || 1,
                unit_cost: unitPrice,
                total_value: unitPrice * (rec.qty || 1)
              }
            ],
            remarks: rec.remarks || ""
          };
        }
      });
    });
  }

  if (v) {
    _currentNav254Voucher = v;
    renderNav254PrintDocument(v);
    document.getElementById("nav254PrintModal")?.classList.remove("hidden");
  } else {
    showToast("Voucher details not found", "error");
  }
}

function renderPrecastInventoryTable() {
  const tbody = document.getElementById("precastInventoryTableBody");
  if (!tbody) return;

  const searchVal = (document.getElementById("precastInventorySearch")?.value || "").toLowerCase().trim();

  // Find all items related to precast
  const isPrecastProduct = (item) => {
    if (!item) return false;
    const desc = (item.description || "").toLowerCase();
    const cat = (item.category || "").toLowerCase();
    const loc = (item.location || "").toLowerCase();
    if (cat.includes("pre-cast") || cat.includes("precast")) return true;
    if (loc.includes("pre-cast") || loc.includes("precast") || loc.includes("g zone") || loc.includes("g-zone")) return true;
    return /cement block|paving|lintel|fence post|curb stone|drain cover|solid block|kerb|concrete ring|unipave|zigzag/i.test(desc);
  };

  const rawInv = store.inventory || [];
  let precastItems = rawInv.filter(isPrecastProduct);

  // If no items in database yet, provide standard default precast catalogue
  if (precastItems.length === 0) {
    const defaults = [
      { description: "4 inch Cement Solid Block", category: "Pre-Cast Products", deno: "Nos", quantity: 0, cost_per_unit: 85, zone_id: "G-Zone", location: "G Zone - Pre-Cast Yard" },
      { description: "6 inch Cement Solid Block", category: "Pre-Cast Products", deno: "Nos", quantity: 0, cost_per_unit: 120, zone_id: "G-Zone", location: "G Zone - Pre-Cast Yard" },
      { description: "8 inch Cement Solid Block", category: "Pre-Cast Products", deno: "Nos", quantity: 0, cost_per_unit: 160, zone_id: "G-Zone", location: "G Zone - Pre-Cast Yard" },
      { description: "Paving Blocks (Unipave / Rectangular)", category: "Pre-Cast Products", deno: "Nos", quantity: 0, cost_per_unit: 65, zone_id: "G-Zone", location: "G Zone - Pre-Cast Yard" },
      { description: "Pre-Cast Concrete Lintel (4' x 9\")", category: "Pre-Cast Products", deno: "Nos", quantity: 0, cost_per_unit: 850, zone_id: "G-Zone", location: "G Zone - Pre-Cast Yard" },
      { description: "Pre-Cast Concrete Fence Post (6' R/C)", category: "Pre-Cast Products", deno: "Nos", quantity: 0, cost_per_unit: 950, zone_id: "G-Zone", location: "G Zone - Pre-Cast Yard" },
      { description: "Pre-Cast Concrete Curb Stone", category: "Pre-Cast Products", deno: "Nos", quantity: 0, cost_per_unit: 620, zone_id: "G-Zone", location: "G Zone - Pre-Cast Yard" },
      { description: "Pre-Cast Drain Cover Slab (2' x 1.5')", category: "Pre-Cast Products", deno: "Nos", quantity: 0, cost_per_unit: 780, zone_id: "G-Zone", location: "G Zone - Pre-Cast Yard" }
    ];
    precastItems = defaults;
  }

  // Calculate KPIs
  let totalStock = 0;
  let productsWithStock = 0;
  precastItems.forEach((i) => {
    const q = parseFloat(i.quantity) || 0;
    totalStock += q;
    if (q > 0) productsWithStock++;
  });

  const cementItem = rawInv.find((i) => (i.description || "").toLowerCase().includes("cement") && !(i.description || "").toLowerCase().includes("block"));
  const cementBags = cementItem ? (cementItem.quantity || 0) : 0;
  const navDispatchedCount = (store.nav254Vouchers || []).length;

  const kpiTotalStock = document.getElementById("pcKpiTotalStock");
  if (kpiTotalStock) kpiTotalStock.textContent = `${totalStock.toLocaleString()} Nos`;

  const kpiProdCount = document.getElementById("pcKpiProductsCount");
  if (kpiProdCount) kpiProdCount.textContent = `${precastItems.length} Records (${productsWithStock} Active)`;

  const kpiNavDisp = document.getElementById("pcKpiNavDispatched");
  if (kpiNavDisp) kpiNavDisp.textContent = `${navDispatchedCount} Vouchers`;

  const kpiRawCement = document.getElementById("pcKpiRawCement");
  if (kpiRawCement) kpiRawCement.textContent = `${cementBags} Bags`;

  // Search Filter
  if (searchVal) {
    precastItems = precastItems.filter((i) =>
      (i.description || "").toLowerCase().includes(searchVal) ||
      (i.location || "").toLowerCase().includes(searchVal) ||
      (i.zone_id || "").toLowerCase().includes(searchVal) ||
      (i.category || "").toLowerCase().includes(searchVal)
    );
  }

  if (precastItems.length === 0) {
    tbody.innerHTML = `<tr><td colspan="7" class="text-center py-6 text-slate-400 font-medium italic">No precast items match your search.</td></tr>`;
    return;
  }

  // Group items merged according to Item Description
  const groupedMap = new Map();
  precastItems.forEach((item) => {
    const key = (item.description || "").trim().toLowerCase();
    if (!groupedMap.has(key)) {
      groupedMap.set(key, {
        description: item.description,
        category: item.category || "Pre-Cast Products",
        deno: item.deno || "Nos",
        entries: [],
      });
    }
    groupedMap.get(key).entries.push(item);
  });

  let rowsHtml = "";

  groupedMap.forEach((group) => {
    const totalGroupQty = group.entries.reduce((sum, e) => sum + (parseFloat(e.quantity) || 0), 0);
    const totalGroupVal = group.entries.reduce((sum, e) => sum + ((parseFloat(e.quantity) || 0) * (parseFloat(e.cost_per_unit || e.cost || 0))), 0);
    const avgUnitCost = totalGroupQty > 0 ? (totalGroupVal / totalGroupQty) : (parseFloat(group.entries[0]?.cost_per_unit || group.entries[0]?.cost || 0));

    const totalStockColor = totalGroupQty > 50 ? "bg-emerald-100 text-emerald-800 border-emerald-300" : (totalGroupQty > 0 ? "bg-amber-100 text-amber-800 border-amber-300" : "bg-rose-100 text-rose-800 border-rose-300");

    const hasMultipleZones = group.entries.length > 1;

    // Main Merged Row for Item Description
    rowsHtml += `
      <tr class="bg-slate-50/90 font-semibold border-t-2 border-slate-200">
        <td class="px-3.5 py-3">
          <div class="font-extrabold text-slate-900 flex items-center gap-2 text-xs">
            <span class="text-base">🧱</span>
            <span>${group.description}</span>
            ${hasMultipleZones ? `<span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-indigo-100 text-indigo-800 border border-indigo-200">${group.entries.length} Zones</span>` : ''}
          </div>
          <div class="text-[10px] text-slate-400 font-mono mt-0.5">Total across all workshops: <strong class="text-slate-700">${totalGroupQty.toLocaleString()} ${group.deno}</strong></div>
        </td>
        <td class="px-3.5 py-3 text-center">
          <span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-indigo-50 text-indigo-700 border border-indigo-200">
            ${group.category}
          </span>
        </td>
        <td class="px-3.5 py-3 text-center text-xs text-slate-600 font-bold">
          ${hasMultipleZones ? `<span>🌐 Combined Stock</span>` : `📍 ${group.entries[0]?.zone_id || group.entries[0]?.location || "G-Zone"}`}
        </td>
        <td class="px-3.5 py-3 text-center">
          <span class="px-2.5 py-1 rounded-lg text-xs font-mono font-black border ${totalStockColor}">
            ${totalGroupQty.toLocaleString()} ${group.deno}
          </span>
        </td>
        <td class="px-3.5 py-3 text-right font-bold text-slate-800 text-xs">
          ${formatCurrency(avgUnitCost)}
        </td>
        <td class="px-3.5 py-3 text-right font-black text-emerald-800 text-xs">
          ${formatCurrency(totalGroupVal)}
        </td>
        <td class="px-3.5 py-3 text-center">
          <div class="flex items-center justify-center gap-1.5">
            <button onclick="openPrecastProductionModal(); document.getElementById('pcProductSelect').value='${group.description.replace(/'/g, "\\'")}'; autoCalculatePrecastRawMaterials();" class="px-2.5 py-1 rounded-lg bg-emerald-600 hover:bg-emerald-700 text-white font-bold text-[10px] shadow-xs cursor-pointer flex items-center gap-1" title="Log new production batch">
              <span>➕ Batch</span>
            </button>
            <button onclick="openNav254Modal();" class="px-2.5 py-1 rounded-lg bg-amber-600 hover:bg-amber-700 text-white font-bold text-[10px] shadow-xs cursor-pointer flex items-center gap-1" title="Issue via NAV 254 Voucher">
              <span>📜 Issue</span>
            </button>
          </div>
        </td>
      </tr>
    `;

    // If multiple zone entries (or even single detailed entry), render clean breakdown rows
    group.entries.forEach((entry) => {
      const eQty = parseFloat(entry.quantity) || 0;
      const eUnitCost = parseFloat(entry.cost_per_unit || entry.cost || 0);
      const eTotalVal = eQty * eUnitCost;
      const eItemId = entry.id || entry._fbKey || "";
      const zoneName = entry.zone_id || (entry.location && entry.location.split("-")[0].trim()) || "G-Zone";

      const zonePillColors = {
        "G-Zone": "bg-amber-100 text-amber-900 border-amber-300",
        "A-Zone": "bg-blue-100 text-blue-900 border-blue-300",
        "B-Zone": "bg-emerald-100 text-emerald-900 border-emerald-300",
        "C-Zone": "bg-purple-100 text-purple-900 border-purple-300",
        "D-Zone": "bg-teal-100 text-teal-900 border-teal-300",
        "E-Zone": "bg-rose-100 text-rose-900 border-rose-300",
        "FH-Zone": "bg-cyan-100 text-cyan-900 border-cyan-300"
      };
      const zonePillClass = zonePillColors[zoneName] || "bg-slate-100 text-slate-800 border-slate-300";

      rowsHtml += `
        <tr class="hover:bg-teal-50/40 transition-colors border-b border-slate-100 bg-white text-xs">
          <td class="px-3.5 py-2.5 pl-8 text-slate-700">
            <div class="flex items-center gap-2">
              <span class="text-slate-400">↳</span>
              <span class="font-medium">${entry.location || `${zoneName} Pre-Cast Store`}</span>
              <span class="text-[10px] text-slate-400 font-mono">(${entry.on_charge_ref || "Stock"})</span>
            </div>
          </td>
          <td class="px-3.5 py-2.5 text-center text-slate-400 text-[11px]">—</td>
          <td class="px-3.5 py-2.5 text-center">
            <span class="px-2 py-0.5 rounded-full text-[10px] font-black border ${zonePillClass}">
              📍 ${zoneName}
            </span>
          </td>
          <td class="px-3.5 py-2.5 text-center font-mono font-bold ${eQty > 0 ? 'text-slate-800' : 'text-slate-400'}">
            ${eQty.toLocaleString()} ${group.deno}
          </td>
          <td class="px-3.5 py-2.5 text-right font-mono">
            ${eItemId ? `
            <button onclick="quickEditUnitCost('${eItemId}', event)" class="font-semibold text-slate-700 hover:text-emerald-700 hover:underline cursor-pointer" title="Click to edit unit price for this zone">
              ${formatCurrency(eUnitCost)} ✏️
            </button>
            ` : `
            <span class="font-semibold text-slate-700">${formatCurrency(eUnitCost)}</span>
            `}
          </td>
          <td class="px-3.5 py-2.5 text-right font-mono font-semibold text-emerald-700">
            ${formatCurrency(eTotalVal)}
          </td>
          <td class="px-3.5 py-2.5 text-center">
            ${eItemId ? `
            <button onclick="openInventoryCard('${eItemId}')" class="px-2 py-1 rounded bg-slate-100 hover:bg-slate-200 text-slate-600 hover:text-slate-900 text-[10px] font-bold cursor-pointer transition-all" title="View Zone Stock Card">
              📋 Card
            </button>
            ` : ''}
          </td>
        </tr>
      `;
    });
  });

  tbody.innerHTML = rowsHtml;
}

// Inward Pending Receipt Badge and Notification Alert updater
function updateTibPendingBadge() {
  const allIssues = store.tempIssues || [];
  const curZone = store.currentZone;
  
  // Pending receipt items for this zone or workshop or project
  const pendingForZone = allIssues.filter((i) => {
    const isPending = i.status === "pending_receipt" || (!i.received_date && !i.actual_return_date && i.status !== "returned" && i.status !== "active");
    if (!isPending) return false;
    if (!curZone) return true;
    return i.zone_id === curZone || i.target_destination === curZone;
  });

  const badgeEl = document.getElementById("tibPendingReceiptBadge");
  if (badgeEl) {
    if (pendingForZone.length > 0) {
      badgeEl.textContent = `${pendingForZone.length} Pending`;
      badgeEl.classList.remove("hidden");
    } else {
      badgeEl.classList.add("hidden");
    }
  }

  const alertBanner = document.getElementById("tibInwardAlertBanner");
  const alertCountEl = document.getElementById("tibInwardAlertCount");
  if (alertBanner && alertCountEl) {
    if (pendingForZone.length > 0) {
      alertCountEl.textContent = `${pendingForZone.length} Pending Receipt`;
      alertBanner.classList.remove("hidden");
    } else {
      alertBanner.classList.add("hidden");
    }
  }
}

function filterToPendingIssues() {
  const catFilter = document.getElementById("tibCategoryFilter");
  const statusFilter = document.getElementById("tibStatusFilter");
  const searchInput = document.getElementById("tibSearchInput");

  if (catFilter) catFilter.value = "all";
  if (statusFilter) statusFilter.value = "pending_receipt";
  if (searchInput) searchInput.value = "";

  setTempIssuePeriod("all");
  renderTempIssuesTable();

  const tbl = document.getElementById("tempIssuesTableBody");
  if (tbl) {
    tbl.scrollIntoView({ behavior: "smooth", block: "center" });
  }
}

